447: func (s *jsonStore) UpdateExpense(id string, expense Expense) error {
448: 	s.mu.Lock()
449: 	defer s.mu.Unlock()
450: 	data, err := s.readExpensesFile(s.filePath)
451: 	if err != nil {
452: 		return fmt.Errorf("failed to read storage file: %v", err)
453: 	}
454: 	found := false
455: 	for i, exp := range data.Expenses {
456: 		if exp.ID == id {
457: 			data.Expenses[i] = expense
458: 			data.Expenses[i].ID = id
459: 			if data.Expenses[i].Currency == "" {
460: 				data.Expenses[i].Currency = s.defaults["currency"]
461: 			}
462: 			found = true
463: 			break
464: 		}
465: 	}
466: 	if !found {
467: 		log.Printf("expense with ID %s not found\n", id)
468: 		return fmt.Errorf("expense with ID %s not found", id)
469: 	}
470: 	log.Printf("Edited expense with ID %s\n", id)
471: 	return s.writeExpensesFile(s.filePath, data)
472: }

