590:                                 <td>${findNextOccurrence(r)}</td>
591:                                 <td>
592:                                     <button class="edit-button" onclick="showRecurringEditModal('${r.id}')"><i class="fa-solid fa-pen-to-square"></i></button>
593:                                     <button class="delete-button" onclick="showRecurringDeleteModal('${r.id}')"><i class="fa-solid fa-trash-can"></i></button>
594:                                 </td>
595:                             </tr>
596:                         `).join('')}
597:                     </tbody>
598:                 </table>`;
599:         }
