681:         // --- Import/Export ---
682:         async function handleCsvImport(event) {
683:             const file = event.target.files[0];
684:             if (!file) return;
685:             const formData = new FormData();
686:             formData.append('file', file);
687:             const messageDiv = document.getElementById('importMessage');
688:             const summaryDiv = document.getElementById('importSummary');
689: 
690:             messageDiv.textContent = 'Importing... this may take a while for large files.';
691:             messageDiv.className = 'form-message';
692:             summaryDiv.style.display = 'none';
693: 
694:             try {
695:                 const response = await fetch('/import/csv', {
696:                     method: 'POST',
697:                     body: formData
698:                 });
699: 
700:                 const result = await response.json();
701: 
702:                 if (response.ok) {
703:                     messageDiv.textContent = 'Import completed!';
704:                     messageDiv.className = 'form-message success';
705:                     summaryDiv.style.display = 'block';
706:                     document.getElementById('summary-processed').textContent = result.total_processed;
707:                     document.getElementById('summary-imported').textContent = result.imported;
708:                     document.getElementById('summary-skipped').textContent = result.skipped;
709:                     document.getElementById('summary-new-categories').textContent = (result.new_categories || []).join(', ') || 'None';
710:                     
711:                     await initialize();
712:                 } else {
713:                     messageDiv.textContent = `Error: ${result.error || 'Failed to import CSV'}`;
714:                     messageDiv.className = 'form-message error';
715:                 }
716:             } catch (error) {
717:                 console.error('Error importing CSV:', error);
718:                 messageDiv.textContent = 'Error: An unexpected error occurred during import.';
719:                 messageDiv.className = 'form-message error';
720:             } finally {
721:                 event.target.value = '';
722:             }
723:         }
724: 
