769:         // --- Initialization ---
770:         async function initialize() {
771:             try {
772:                 const [configResponse, expensesResponse, recurringExpensesResponse] = await Promise.all([
773:                     fetch('/config'),
774:                     fetch('/expenses'),
775:                     fetch('/recurring-expenses')
776:                 ]);
777:                 if (!configResponse.ok) throw new Error('Failed to fetch configuration');
778:                 const config = await configResponse.json();
779:                 if (!expensesResponse.ok) throw new Error('Failed to fetch expenses');
780:                 const expenses = await expensesResponse.json();
781:                 if (!recurringExpensesResponse.ok) throw new Error('Failed to fetch recurring expenses');
782:                 recurringExpenses = await recurringExpensesResponse.json() || [];
783: 
784:                 categories = [...config.categories];
785:                 currentCurrency = config.currency;
786:                 currentStartDate = config.startDate;
787:                 allTags.clear();
788:                 (expenses || []).forEach(exp => (exp.tags || []).forEach(tag => allTags.add(tag)));
789:                 (recurringExpenses || []).forEach(exp => (exp.tags || []).forEach(tag => allTags.add(tag)));
790: 
791:                 renderCategories();
792:                 populateCurrencySelect();
793:                 populateStartDateInput();
794:                 document.getElementById('recurringCategory').innerHTML = categories.map(c => `<option value="${c}">${c}</option>`).join('');
795:                 document.getElementById('editRecurringCategory').innerHTML = categories.map(c => `<option value="${c}">${c}</option>`).join('');
796:                 renderRecurringExpenses(recurringExpenses);
797: 
798:                 createTagInput('tags-input', 'selected-tags', 'tags-dropdown', addFormSelectedTags);
799:                 fetch('/version').then(r => r.ok ? r.text() : 'dev').then(version => {
800:                     const link = document.getElementById('version-link');
801:                     link.textContent = version;
802:                     if (version !== 'dev') link.href = `https://github.com/tanq16/expenseowl/releases/tag/${version}`;
803:                 }).catch(e => console.error('Failed to fetch version:', e));
804: 
805:             } catch (error) {
806:                 console.error('Failed to initialize settings:', error);
807:                 showMessage('categoriesMessage', 'Failed to load settings', false);
808:             }
809:         }
